begin;
create function pg_temp.assert_unified(ok boolean,message text) returns void language plpgsql as $$begin if ok is not true then raise exception 'FAIL: %',message;end if;end $$;
create function pg_temp.assert_books(t uuid) returns void language plpgsql security definer set search_path='' as $$declare p jsonb;begin
 perform pg_temp.assert_unified(not exists(select 1 from public.accounting_lines where tenant_id=t group by journal_id having sum(amount)<>0),'Every journal balances');
 perform pg_temp.assert_unified(not exists(select 1 from public.wallets w where w.tenant_id=t and w.balance<>coalesce((select sum(amount) from public.accounting_lines where tenant_id=t and account='cash' and entity_id=w.wallet_id),0)),'Journal cash equals each real wallet');
 perform pg_temp.assert_unified(not exists(select 1 from public.inventory_costs c join public.items i using(tenant_id,item_id) where c.tenant_id=t and (c.filled_quantity<>i.filled_quantity or c.empty_quantity<>i.empty_quantity or c.filled_value+c.empty_value<>coalesce((select sum(amount) from public.accounting_lines l where l.tenant_id=t and l.entity_id=c.item_id and l.account in ('inventory_lpg','inventory_stove')),0))),'Inventory quantity and journal carrying value reconcile');
 p:=app_private.accounting_position(array[t],(now() at time zone 'Asia/Dhaka')::date);
 perform pg_temp.assert_unified((p->>'assets')::numeric=(p->>'liabilities')::numeric+(p->>'equity')::numeric,'Assets = Liabilities + Equity');
end $$;
create function pg_temp.seed_unified_prices(t uuid,i uuid) returns void language sql security definer set search_path='' as $$ insert into public.price_books(tenant_id,item_id,customer_tier,price_type,price,effective_from) values(t,i,'retail','package',200,now());$$;
create function pg_temp.seed_lpg_prices(t uuid,i uuid) returns void language sql security definer set search_path='' as $$ insert into public.price_books(tenant_id,item_id,customer_tier,price_type,price,effective_from) values(t,i,'retail','package',4000,now()),(t,i,'retail','refill',1200,now());$$;
create function pg_temp.reject_unified(q text,expected text) returns void language plpgsql as $$begin begin execute q;exception when others then if position(lower(expected) in lower(sqlerrm))=0 then raise exception 'Expected %; got %',expected,sqlerrm;end if;return;end;raise exception 'Expected rejection: %',expected;end $$;
create function pg_temp.assert_clear_transit(t uuid,p uuid) returns void language plpgsql security definer set search_path='' as $$begin perform pg_temp.assert_unified((select coalesce(sum(amount),0) from public.accounting_lines where tenant_id=t and account='inventory_transit' and entity_id=p)=0,'Invoice and dispatched-shell clearing including rounding');end $$;
grant execute on function pg_temp.assert_clear_transit(uuid,uuid) to authenticated;
grant execute on function pg_temp.seed_lpg_prices(uuid,uuid),pg_temp.reject_unified(text,text) to authenticated;
grant execute on function pg_temp.seed_unified_prices(uuid,uuid) to authenticated;
grant execute on function pg_temp.assert_unified(boolean,text),pg_temp.assert_books(uuid) to authenticated;
insert into auth.users(id,email,is_anonymous) values('ae010000-0000-4000-8000-000000000001','unified-owner@example.invalid',false),('ae020000-0000-4000-8000-000000000001','unified-other@example.invalid',false);
set local role authenticated;
select set_config('request.jwt.claim.sub','ae010000-0000-4000-8000-000000000001',true);
select public.setup_business('Unified accounting disposable fixture','Owner');
select set_config('request.jwt.claim.sub','ae020000-0000-4000-8000-000000000001',true);
select public.setup_business('Unified accounting other tenant','Other');
select set_config('request.jwt.claim.sub','ae010000-0000-4000-8000-000000000001',true);
do $$declare t uuid:=app_private.current_tenant_id();d date:=(now() at time zone 'Asia/Dhaka')::date;tid uuid;item uuid;cash uuid;bank uuid;pid uuid;sid uuid;loan uuid;asset uuid;commission uuid;req uuid;body jsonb;r jsonb;report jsonb;before_cash numeric;begin
 select type_id into tid from public.get_stove_product_types() where name='Single Stove';
 perform pg_temp.assert_unified(tid is not null,'Default stove types seeded');
 item:=(public.save_stove_product(jsonb_build_object('name','Fixture stove','type_id',tid),gen_random_uuid())->>'item_id')::uuid;
 select wallet_id into cash from public.get_payment_wallets() where type='cash';select wallet_id into bank from public.get_payment_wallets() where type='dealership';
 perform public.accounting_operation(jsonb_build_object('action','opening_cash','date',d,'description','Opening cash','amount',10000,'wallet_id',cash),gen_random_uuid());
 body:=jsonb_build_object('item_id',item,'kind','opening','filled_quantity',10,'empty_quantity',0,'filled_unit_cost',100,'reason','Verified opening count');req:=gen_random_uuid();r:=public.adjust_inventory(body,req);
 perform pg_temp.assert_unified(public.adjust_inventory(body,req)=r,'Inventory retry posts once');perform pg_temp.assert_books(t);
 perform pg_temp.seed_unified_prices(t,item);
 pid:=(public.create_purchase(jsonb_build_object('business_category','stove','supplier_name','Fixture supplier','request_id',gen_random_uuid(),'items',jsonb_build_array(jsonb_build_object('item_id',item,'type','package','quantity',10,'unit_price',300))))->>'purchase_id')::uuid;
 perform public.record_purchase_payment(pid,jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',500),jsonb_build_object('wallet_id',bank,'amount',200)),gen_random_uuid());
 perform public.receive_purchase(pid,2);perform pg_temp.assert_books(t);
 perform pg_temp.assert_unified((public.get_inventory_cost_history(item)->'pool'->>'filled_value')::numeric=4000,'Weighted-average pool includes opening and unpaid purchase costs');
 sid:=(public.create_pos_sale('01700000491','Fixture buyer',null,null,'retail',0,0,null,jsonb_build_array(jsonb_build_object('item_id',item,'type','package','quantity',2,'unit_price',200)),null,gen_random_uuid(),jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',150)),null)->>'sale_id')::uuid;
 perform pg_temp.assert_books(t);
 perform pg_temp.assert_unified((public.get_inventory_cost_history(item)->'pool'->>'filled_value')::numeric=3600,'Sale consumes weighted-average inventory without sale buying prices');
 perform public.collect_sale_payment(sid,jsonb_build_array(jsonb_build_object('wallet_id',bank,'amount',250)),gen_random_uuid());perform pg_temp.assert_books(t);
 perform public.adjust_inventory(jsonb_build_object('item_id',item,'kind','damaged','filled_quantity',-1,'empty_quantity',0,'reason','Damaged fixture unit'),gen_random_uuid());perform pg_temp.assert_books(t);
 report:=public.get_finance_analysis(jsonb_build_object('from',d,'to',d,'business_id',t,'grain','day'));
 perform pg_temp.assert_unified((report->'totals'->>'profit')::numeric=-200,'Opening equity is not income; inventory loss is expense');
 perform pg_temp.assert_unified((report->'totals'->>'profit')::numeric=(report->'totals'->>'position_profit')::numeric,'Period P&L equals change in net assets adjusted for equity');
 loan:=(public.accounting_operation(jsonb_build_object('action','loan_create','date',d,'description','Fixture loan','lender','Fixture lender','amount',1000,'wallet_id',cash),gen_random_uuid())->>'id')::uuid;
 perform public.accounting_operation(jsonb_build_object('action','loan_repay','date',d,'description','Partial principal','loan_id',loan,'amount',200,'wallet_id',bank),gen_random_uuid());perform pg_temp.assert_books(t);
 report:=public.get_finance_analysis(jsonb_build_object('from',d,'to',d,'business_id',t,'grain','day'));perform pg_temp.assert_unified((report->'totals'->>'profit')::numeric=-200,'Loan principal never changes profit');
 asset:=(public.accounting_operation(jsonb_build_object('action','asset_register','date',d,'description','Equipment acquisition','name','Fixture equipment','kind','equipment','funding','wallet','amount',500,'wallet_id',cash),gen_random_uuid())->>'id')::uuid;
 perform public.accounting_operation(jsonb_build_object('action','asset_depreciate','date',d,'description','Recorded depreciation','asset_id',asset,'amount',100),gen_random_uuid());
 perform public.accounting_operation(jsonb_build_object('action','asset_dispose','date',d,'description','Dismantled fixture','asset_id',asset,'method','dismantled','proceeds',450,'expense',20,'wallet_id',cash),gen_random_uuid());perform pg_temp.assert_books(t);
 report:=public.get_finance_analysis(jsonb_build_object('from',d,'to',d,'business_id',t,'grain','day'));perform pg_temp.assert_unified((report->'totals'->>'profit')::numeric=-270,'Asset disposal recognizes only net proceeds less book value');
 commission:=(public.accounting_operation(jsonb_build_object('action','commission_earn','date',d,'description','Earned supplier commission','supplier_name','Fixture supplier','business_category','stove','amount',200),gen_random_uuid())->>'id')::uuid;
 perform public.accounting_operation(jsonb_build_object('action','commission_apply','date',d,'description','Settle prior earned credit','commission_id',commission,'purchase_id',pid,'amount',100),gen_random_uuid());perform pg_temp.assert_books(t);
 report:=public.get_finance_analysis(jsonb_build_object('from',d,'to',d,'business_id',t,'grain','day'));perform pg_temp.assert_unified((report->'totals'->>'profit')::numeric=-70,'Earned commission counted once, settlement is not income');
 perform pg_temp.assert_unified((report->'totals'->>'profit')::numeric=(report->'totals'->>'position_profit')::numeric,'Final net-assets reconciliation');
 -- Reversal and partial refunds remain separate from operational cancellation.
 perform public.reverse_sale(sid,'Returned fixture products','CANCEL',gen_random_uuid());perform pg_temp.assert_books(t);
 perform public.refund_sale(sid,jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',150)),gen_random_uuid());
 perform public.refund_sale(sid,jsonb_build_array(jsonb_build_object('wallet_id',bank,'amount',250)),gen_random_uuid());perform pg_temp.assert_books(t);
 perform pg_temp.assert_unified((public.get_sale_settlement(sid)->>'refund_due')::numeric=0,'Cancelled sale refunds settle only received payments');
 select * into r from public.get_purchases_by_ids(array[pid]);before_cash:=(r->>'revision')::numeric;
 perform public.initiate_purchase_cancellation(pid,before_cash::integer,'CANCEL',gen_random_uuid());perform pg_temp.assert_books(t);
 perform pg_temp.assert_unified((select (x->>'used')::numeric from jsonb_array_elements(public.get_accounting_register('commissions')->'entries') x where (x->>'commission_id')::uuid=commission)=0,'Cancellation restores applied supplier credits without extra income');
 r:=public.get_purchase_settlement(pid);
 perform public.refund_purchase(pid,(r->'obligations'->0->>'obligation_id')::uuid,jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',700)),gen_random_uuid());perform pg_temp.assert_books(t);
 -- Supplemental opening debt is paid without another operating expense.
 req:=gen_random_uuid();perform public.accounting_operation(jsonb_build_object('action','opening_entry','account','supplier_payable','amount',300,'description','Supplemental opening supplier','date',d),req);
 perform public.accounting_operation(jsonb_build_object('action','settle_obligation','obligation_id',req,'wallet_id',cash,'amount',100,'description','Opening supplier partial settlement','date',d),gen_random_uuid());perform pg_temp.assert_books(t);
 report:=public.get_finance_analysis(jsonb_build_object('from',d-1,'to',d,'business_id',t,'grain','day'));perform pg_temp.assert_unified(report->'totals'->>'profit' is not null and (report->'totals'->>'profit')::numeric=(report->'totals'->>'position_profit')::numeric,'New businesses report empty earlier periods and reconcile subsequent activity');
end $$;
do $$declare t uuid:=app_private.current_tenant_id();d date:=(now() at time zone 'Asia/Dhaka')::date;b uuid;plant uuid;i uuid;cash uuid;driver uuid;v uuid;tr uuid;pid uuid;sid uuid;asset uuid;req uuid;report jsonb;r jsonb;value_before numeric;value_after numeric;begin
 select wallet_id into cash from public.get_payment_wallets() where type='cash';
 b:=(public.create_lpg_brand('Unified fixture LPG',null)->>'brand_id')::uuid;
 plant:=(public.create_gas_plant('Unified fixture plant',b,'Dhaka')->>'plant_id')::uuid;
 insert into public.items(tenant_id,brand_id,size_kg,mouth_size) values(t,b,12,'22mm') returning item_id into i;
 perform public.adjust_inventory(jsonb_build_object('item_id',i,'kind','opening','filled_quantity',20,'empty_quantity',20,'filled_unit_cost',2500,'empty_unit_cost',1500,'reason','LPG valued opening'),gen_random_uuid());
 perform pg_temp.seed_lpg_prices(t,i);
 driver:=(public.save_employee(jsonb_build_object('name','Unified fixture driver','employee_type_name','Driver','business_unit','truck_business','phones',jsonb_build_array(jsonb_build_object('phone','01700000492','is_primary',true)),'terms',jsonb_build_object('monthly_salary',1000,'effective_from',d,'is_active',true)),gen_random_uuid())->>'employee_id')::uuid;
 v:=(public.save_vehicle(jsonb_build_object('name','Unified fixture truck','serial_no','UNIFIED-492','capacity',100,'driver_employee_id',driver,'book_value',50000,'funding','opening'),gen_random_uuid())->>'vehicle_id')::uuid;
 perform public.set_vehicle_availability(v,false,'Fixture maintenance',gen_random_uuid());
 perform pg_temp.reject_unified(format('select public.create_custom_transit(%L::jsonb,%L::uuid)',jsonb_build_object('vehicle_id',v,'fee',500,'client_name','Fixture client','destination','Dhaka'),gen_random_uuid()),'out of service');
 perform public.set_vehicle_availability(v,true,'Maintenance finished',gen_random_uuid());
 pid:=(public.create_purchase(jsonb_build_object('request_id',gen_random_uuid(),'plant_id',plant,'vehicle_id',v,'commission',0.01,'transport_cost',200,'labour_cost',1,'items',jsonb_build_array(jsonb_build_object('item_id',i,'type','refill','quantity',2,'unit_price',1000),jsonb_build_object('item_id',i,'type','package','quantity',1,'unit_price',2500))))->>'purchase_id')::uuid;
 perform public.dispatch_purchase(pid,1);perform pg_temp.assert_books(t);perform public.receive_purchase(pid,2);perform pg_temp.assert_books(t);
 perform pg_temp.assert_clear_transit(t,pid);
 -- A physical bottle return transfers an existing asset back into inventory.
 sid:=(public.create_pos_sale('01700000493','LPG fixture buyer',null,null,'retail',0,0,null,jsonb_build_array(jsonb_build_object('item_id',i,'type','refill','quantity',1,'unit_price',1200),jsonb_build_object('item_id',i,'type','empty_return','quantity',1,'unit_price',0)),null,gen_random_uuid(),'[]',jsonb_build_object('lines','[]'::jsonb,'note','Deferred bottle')) ->>'sale_id')::uuid;
 report:=public.get_finance_analysis(jsonb_build_object('from',d,'to',d,'business_id',t,'grain','day'));value_before:=(report->'totals'->>'profit')::numeric;
 perform public.collect_sale_bottles(sid,jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('received_item_id',i,'quantity',1)),'note','Actual later bottle','fee',0),gen_random_uuid());
 report:=public.get_finance_analysis(jsonb_build_object('from',d,'to',d,'business_id',t,'grain','day'));value_after:=(report->'totals'->>'profit')::numeric;
 perform pg_temp.assert_unified(value_before=value_after,'Collecting an owed bottle does not create profit');perform pg_temp.assert_books(t);
 perform public.reverse_sale(sid,'All sold goods and collected bottles returned','CANCEL',gen_random_uuid());
 sid:=(public.create_pos_sale('01700000494','Excess bottle fixture buyer',null,null,'retail',0,0,null,jsonb_build_array(jsonb_build_object('item_id',i,'type','refill','quantity',1,'unit_price',1200),jsonb_build_object('item_id',i,'type','empty_return','quantity',1,'unit_price',0)),null,gen_random_uuid(),'[]',jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('received_item_id',i,'quantity',2,'acknowledged',true)),'note','Acknowledged excess bottle')) ->>'sale_id')::uuid;
 perform public.reverse_sale(sid,'All sold goods returned; collected bottles returned to customer','CANCEL',gen_random_uuid());
 perform pg_temp.assert_unified(coalesce((select sum((x->>'amount')::numeric) from jsonb_array_elements(public.get_finance_analysis(jsonb_build_object('from',d,'to',d,'business_id',t,'grain','day'))->'categories') x where x->>'account'='other_income'),0)=0,'Cancelling excess bottle receipts reverses the original stock gain instead of hiding it in negative COGS');
 perform pg_temp.assert_books(t);

 tr:=(public.create_custom_transit(jsonb_build_object('vehicle_id',v,'fee',500,'client_name','External client','destination','Dhaka'),gen_random_uuid())->>'transit_id')::uuid;
 perform public.set_vehicle_availability(v,false,'Active vehicle may finish this journey',gen_random_uuid());
 perform public.save_transit_costs(tr,'{"driver_cost":50,"helper_cost":0,"oil_cost":20,"others_cost":0,"additional_costs":[]}',1);
 perform public.record_operating_payment(jsonb_build_object('transit_id',tr,'kind','client_receipt','payment_date',d,'payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',300))),gen_random_uuid());
 perform public.record_operating_payment(jsonb_build_object('transit_id',tr,'kind','expense','payment_date',d,'payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',20))),gen_random_uuid());
 perform public.employee_payment_operation(jsonb_build_object('action','pay','items',jsonb_build_array(jsonb_build_object('employee_id',driver,'kind','trips','trip_count',1,'transit_id',tr,'trip_role','driver','payment_date',d,'payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',50))))),gen_random_uuid());
 perform public.employee_payment_operation(jsonb_build_object('action','pay','items',jsonb_build_array(jsonb_build_object('employee_id',driver,'kind','salary','period',date_trunc('month',d)::date,'payment_date',d,'payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',200))))),gen_random_uuid());perform pg_temp.assert_books(t);
 r:=public.get_transit(tr);perform public.transition_transit(tr,'return',(r->>'revision')::integer);
 r:=public.get_vehicle(v);asset:=(r->'asset'->>'asset_id')::uuid;
 perform public.accounting_operation(jsonb_build_object('action','asset_depreciate','asset_id',asset,'amount',1000,'date',d,'description','Truck depreciation'),gen_random_uuid());
 perform public.accounting_operation(jsonb_build_object('action','asset_dispose','asset_id',asset,'method','sold','proceeds',50000,'expense',100,'wallet_id',cash,'date',d,'description','Truck sold after return'),gen_random_uuid());
 perform pg_temp.reject_unified(format('select public.set_vehicle_availability(%L,true,%L,%L)',v,'Try restore retired',gen_random_uuid()),'permanently retired');
 perform pg_temp.reject_unified(format('select public.create_custom_transit(%L::jsonb,%L::uuid)',jsonb_build_object('vehicle_id',v,'fee',500,'client_name','Fixture client','destination','Dhaka'),gen_random_uuid()),'retired');
 select to_jsonb(c) into r from public.get_spending_categories() c where c.name='Interest';
 perform public.record_spending(jsonb_build_object('category_id',r->>'category_id','category_name','Interest','classification','cost','wallet_id',cash,'amount',10,'spending_date',d,'description','Manual paid CC interest'),gen_random_uuid());
 perform pg_temp.assert_books(t);report:=public.get_finance_analysis(jsonb_build_object('from',d,'to',d,'business_id',t,'grain','day'));perform pg_temp.assert_unified((report->'totals'->>'profit')::numeric=(report->'totals'->>'position_profit')::numeric,'LPG/logistics/payroll/interest/disposal profit reconciles to period net assets');
end $$;
