reset role;
update public.accounting_periods set started_at=(now() at time zone 'Asia/Dhaka')::date-40 where tenant_id=(select tenant_id from public.user_profiles where user_id='ae040000-0000-4000-8000-000000000001');
set local role authenticated;
do $$declare t uuid:=app_private.current_tenant_id();d date:=(now() at time zone 'Asia/Dhaka')::date;cash uuid;bank uuid;loan uuid;asset uuid;credit uuid;item uuid;tid uuid;pid uuid;r jsonb;report jsonb;begin
 select wallet_id into cash from public.get_payment_wallets() where type='cash';select wallet_id into bank from public.get_payment_wallets() where type='dealership';
 perform public.accounting_operation(jsonb_build_object('action','opening_cash','wallet_id',cash,'amount',10000,'date',d-40,'description','Evidenced opening cash'),gen_random_uuid());
 credit:=(public.accounting_operation(jsonb_build_object('action','commission_earn','business_category','stove','supplier_name','Period supplier','amount',200,'date',d-35,'description','Prior-period earned commission'),gen_random_uuid())->>'id')::uuid;
 loan:=(public.accounting_operation(jsonb_build_object('action','loan_create','lender','Period lender','wallet_id',cash,'amount',1000,'date',d-30,'description','Earlier loan receipt'),gen_random_uuid())->>'id')::uuid;
 asset:=(public.accounting_operation(jsonb_build_object('action','asset_register','name','Period equipment','kind','equipment','funding','wallet','wallet_id',cash,'amount',500,'date',d-20,'description','Equipment cost'),gen_random_uuid())->>'id')::uuid;
 perform public.accounting_operation(jsonb_build_object('action','asset_depreciate','asset_id',asset,'amount',100,'date',d-10,'description','Prior-period depreciation'),gen_random_uuid());
 select type_id into tid from public.get_stove_product_types() limit 1;
 item:=(public.save_stove_product(jsonb_build_object('name','Period stove','type_id',tid),gen_random_uuid())->>'item_id')::uuid;
 pid:=(public.create_purchase(jsonb_build_object('business_category','stove','supplier_name','Period supplier','request_id',gen_random_uuid(),'items',jsonb_build_array(jsonb_build_object('item_id',item,'type','package','quantity',10,'unit_price',20))))->>'purchase_id')::uuid;
 perform public.receive_purchase(pid,1);
 perform public.accounting_operation(jsonb_build_object('action','commission_apply','commission_id',credit,'purchase_id',pid,'amount',200,'date',d,'description','Use prior commission'),gen_random_uuid());
 perform public.accounting_operation(jsonb_build_object('action','loan_repay','loan_id',loan,'wallet_id',cash,'amount',200,'date',d,'description','Current principal repayment'),gen_random_uuid());
 perform public.accounting_operation(jsonb_build_object('action','asset_dispose','asset_id',asset,'method','dismantled','proceeds',450,'expense',20,'wallet_id',cash,'date',d,'description','Current disposal'),gen_random_uuid());
 report:=public.get_finance_analysis(jsonb_build_object('business_id',t,'from',d-35,'to',d-35,'grain','day'));
 perform pg_temp.assert_unified((report->'totals'->>'profit')::numeric=200 and (report->'totals'->>'position_profit')::numeric=200,'Commission belongs to earned period');
 report:=public.get_finance_analysis(jsonb_build_object('business_id',t,'from',d,'to',d,'grain','day'));
 perform pg_temp.assert_unified((report->'totals'->>'profit')::numeric=30 and (report->'totals'->>'position_profit')::numeric=30,'Later credit application / principal settlement creates no profit; disposal uses remaining book value');
 perform public.accounting_operation(jsonb_build_object('action','capital','wallet_id',cash,'amount',500,'date',d,'description','Current capital contribution'),gen_random_uuid());
 select to_jsonb(c) into r from public.get_spending_categories() c where c.name='Home';
 perform public.record_spending(jsonb_build_object('category_id',r->>'category_id','category_name','Home','classification','withdrawal','wallet_id',cash,'amount',50,'spending_date',d,'description','Owner withdrawal'),gen_random_uuid());
 select to_jsonb(c) into r from public.get_spending_categories() c where c.name='Interest';
 perform public.record_spending(jsonb_build_object('category_id',r->>'category_id','category_name','Interest','classification','cost','wallet_id',cash,'amount',7,'spending_date',d,'description','Manually recorded interest'),gen_random_uuid());
 perform public.move_wallet_money(jsonb_build_object('action','transfer','wallet_id',cash,'destination_id',bank,'amount',100,'reason','Internal funds transfer'),gen_random_uuid());
 report:=public.get_finance_analysis(jsonb_build_object('business_id',t,'from',d,'to',d,'grain','day'));
 perform pg_temp.assert_unified((report->'totals'->>'profit')::numeric=23 and (report->'totals'->>'position_profit')::numeric=23,'Capital and withdrawals excluded; paid interest reduces profit');
 perform pg_temp.assert_unified((report->'totals'->>'cash_flow')::numeric=673 and (report->'totals'->>'transfers')::numeric=100,'Cash flow reconciles with financing, investing, interest and zero-net transfers');
 -- Credit-funded assets and unpaid operating costs use the same obligation
 -- settlement control without a second expense when cash is paid.
 perform public.accounting_operation(jsonb_build_object('action','asset_register','name','Credit equipment','kind','equipment','funding','credit','amount',1000,'date',d,'description','Equipment acquired on credit'),gen_random_uuid());
 select x into r from jsonb_array_elements(public.get_accounting_register('obligations')->'entries') x where x->>'description'='Asset payable: Equipment acquired on credit';
 perform public.accounting_operation(jsonb_build_object('action','settle_obligation','obligation_id',r->>'obligation_id','wallet_id',cash,'amount',300,'date',d,'description','Partial asset payment'),gen_random_uuid());
 perform public.accounting_operation(jsonb_build_object('action','expense_accrue','amount',100,'date',d,'description','Unpaid business operating cost'),gen_random_uuid());
 select x into r from jsonb_array_elements(public.get_accounting_register('obligations')->'entries') x where x->>'description'='Unpaid business operating cost';
 perform public.accounting_operation(jsonb_build_object('action','settle_obligation','obligation_id',r->>'obligation_id','wallet_id',cash,'amount',50,'date',d,'description','Partial operating payment'),gen_random_uuid());
 report:=public.get_finance_analysis(jsonb_build_object('business_id',t,'from',d,'to',d,'grain','day'));
 perform pg_temp.assert_unified((report->'totals'->>'profit')::numeric=-77 and (report->'totals'->>'position_profit')::numeric=-77,'Credit assets are not expenses; incurred operating costs are expensed once');
 perform pg_temp.assert_unified((report->'totals'->>'cash_flow')::numeric=323,'Asset and operating obligation settlements retain correct cash flow');
 perform pg_temp.assert_books(t);
 -- Supplemental opening evidence entered after a reporting period starts is
 -- an equity movement, never operating profit or period cash flow.
 perform public.accounting_operation(jsonb_build_object('action','opening_cash','wallet_id',cash,'amount',123,'date',d,'description','Later opening cash evidence'),gen_random_uuid());
 perform public.accounting_operation(jsonb_build_object('action','asset_register','name','Later opening equipment','kind','equipment','funding','opening','amount',200,'date',d,'description','Later opening asset evidence'),gen_random_uuid());
 perform public.accounting_operation(jsonb_build_object('action','asset_register','name','Fully depreciated opening equipment','kind','equipment','funding','opening','amount',0,'date',d,'description','Explicit zero remaining book cost'),gen_random_uuid());
 perform public.accounting_operation(jsonb_build_object('action','opening_entry','account','supplier_payable','amount',50,'date',d,'description','Later opening liability evidence'),gen_random_uuid());
 perform public.accounting_operation(jsonb_build_object('action','loan_create','lender','Opening lender','opening',true,'amount',70,'date',d,'description','Later opening principal evidence'),gen_random_uuid());
 perform public.adjust_inventory(jsonb_build_object('item_id',item,'kind','opening','filled_quantity',2,'empty_quantity',0,'filled_unit_cost',25.5,'reason','Later opening inventory evidence'),gen_random_uuid());
 report:=public.get_finance_analysis(jsonb_build_object('business_id',t,'from',d-5,'to',d,'grain','day'));
 perform pg_temp.assert_unified((report->'totals'->>'profit')::numeric=-77 and (report->'totals'->>'position_profit')::numeric=-77,'Supplemental opening positions within a reporting period are excluded from net-assets profit');
 perform pg_temp.assert_unified((report->'totals'->>'equity_adjustments')::numeric=254 and (report->'totals'->>'cash_flow')::numeric=323,'Mid-period opening equity adjustments reconcile without fictitious cash flow');
 report:=public.get_finance_analysis(jsonb_build_object('business_id',t,'from',d,'to',d,'grain','day'));
 perform pg_temp.assert_unified((report->'totals'->>'profit')::numeric=(report->'totals'->>'position_profit')::numeric and (report->'totals'->>'equity_adjustments')::numeric=0,'Opening entries on the period start are included once in the opening position');
 perform pg_temp.assert_books(t);
end $$;
